     .teams-editor {
       border: 1px solid #d8e0ea; border-radius: 6px; background-color: #ffffff; display: flex; flex-direction: column; overflow: visible; font-family: 'Segoe UI', sans-serif; position: relative; transition: background-color 0.3s;
     }
     .teams-editor.dark-mode { background-color: #242424; border-color: #444; }

     /* Área de Texto */
     .te-content {
       padding: 16px 16px 24px 16px; min-height: 120px; max-height: 350px; overflow-y: auto; outline: none; line-height: 1.5; font-size: 0.95rem; color: #242424;
     }
     .teams-editor.dark-mode .te-content { color: #ffffff; }

     /* Placeholder com ícone do Copilot */
     .te-content:empty:before {
       content: attr(data-placeholder); color: #8a8a8a; pointer-events: none;
     }

     /* Barras de Ferramentas */
     .te-format-bar, .te-bottom-bar { display: flex; align-items: center; padding: 6px 12px; gap: 2px; }

     .te-format-bar { background-color: #f5f5f5; border-top: 1px solid #e0e0e0; display: none; flex-wrap: wrap; }
     .teams-editor.dark-mode .te-format-bar { background-color: #1a1a1a; border-top-color: #333; }

     .te-bottom-bar { background-color: #ffffff; border-top: 1px solid #e0e0e0; border-bottom-left-radius: 6px; border-bottom-right-radius: 6px; position: relative; }
     .teams-editor.dark-mode .te-bottom-bar { background-color: #141414; border-top-color: #333; }

     /* Botões da Toolbar */
     .te-btn {
       background: transparent; border: none; color: #444; height: 32px; min-width: 32px; padding: 0 6px; border-radius: 4px; display: inline-flex; align-items: center; justify-content: center; cursor: pointer; font-family: inherit; transition: background 0.1s;
     }
     .te-btn .material-symbols-outlined { font-size: 20px; font-weight: 300; }
     .te-btn:hover, .te-btn.active { background-color: #e0e0e0; color: #000; }
     .teams-editor.dark-mode .te-btn { color: #d1d1d1; }
     .teams-editor.dark-mode .te-btn:hover, .teams-editor.dark-mode .te-btn.active { background-color: #333; color: #fff; }

     .te-divider { width: 1px; height: 20px; background-color: #ccc; margin: 0 4px; }
     .teams-editor.dark-mode .te-divider { background-color: #444; }

     /* Estilo específico para o botão de Cor/Marcador */
     .te-color-btn { display: flex; flex-direction: column; align-items: center; justify-content: center; line-height: 1; margin-top: 2px; }
     .te-color-btn span:first-child { font-weight: bold; font-size: 14px; }
     .te-color-bar { width: 12px; height: 3px; border-radius: 2px; margin-top: 1px; }

