             if (card._pdfPreview) {
               const scrollPosition = window.scrollY;
               card._pdfPreview.src = `${data}#toolbar=0&navpanes=0&scrollbar=0`;
               card._pdfPreview.hidden = false;
               restoreEditorAfterPdfFocus(card._pdfPreview, scrollPosition);
             }
           },
           action: 'anexar'
         }));
