     .te-dropdown-header { padding: 4px 16px 8px 16px; font-size: 0.8rem; color: #667085; font-weight: 600; }
     .teams-editor.dark-mode .te-dropdown-header { color: #a1a1a1; }
     .te-dropdown-item {
       padding: 8px 16px; display: flex; align-items: center; gap: 12px; color: #242424; cursor: pointer; font-size: 0.9rem; border: none; background: transparent; width: 100%; text-align: left;
     }
     .te-dropdown-item:hover { background: #f0f0f0; }
     .teams-editor.dark-mode .te-dropdown-item { color: #d1d1d1; }
     .teams-editor.dark-mode .te-dropdown-item:hover { background: #3d3d3d; }

     .te-picker-wrapper { position: relative; }
     .te-emoji-menu {
       position: absolute; bottom: 100%; left: 0; margin-bottom: 8px; width: 320px; max-height: 300px; overflow-y: auto;
