     .teams-editor.dark-mode .te-emoji-item:hover { background: #3d3d3d; }

     .te-image-attachment { display: inline-block; position: relative; max-width: 100%; box-sizing: border-box; vertical-align: baseline; line-height: 0; }
     .te-image-attachment img { display: block; width: 100%; height: auto; transform-origin: center; }
     .te-image-attachment.is-selected { outline: 1px solid #8b8bff; }
     .te-image-rotate {
       position: absolute; z-index: 4; left: 50%; top: 0; transform: translate(-50%, -50%); width: 26px; height: 26px;
       display: grid; place-items: center; border: 0; border-radius: 50%; background: #292929; color: #fff; cursor: grab; line-height: 1;
     }
     .te-image-rotate .material-symbols-outlined { font-size: 18px; }
     .te-image-handle {
       position: absolute; z-index: 2; width: 14px; height: 14px; padding: 0; border: 2px solid #b8b8b8;
       border-radius: 50%; background: #fff; transform: translate(-50%, -50%);
     }
     .te-image-handle[data-direction="n"], .te-image-handle[data-direction="s"] { left: 50%; cursor: ns-resize; }
     .te-image-handle[data-direction="e"], .te-image-handle[data-direction="w"] { top: 50%; cursor: ew-resize; }
     .te-image-handle[data-direction="nw"], .te-image-handle[data-direction="se"] { cursor: nwse-resize; }
