 .section-heading h2 {
   margin: 0;
   padding: 0;
   border: 0;
   color: #454443;
   font-size: 1rem;
   font-weight: 600;
 }
 .category-card {
   width: 250px;
   min-height: 242px;
   padding: 13px;
   border-color: #e5e5e5;
   border-radius: 10px;
   box-shadow: 0 2px 5px rgba(0, 0, 0, .09);
 }
 .category-card:hover {
   transform: translateY(-2px);
   border-color: #d2d2d2;
   box-shadow: 0 5px 12px rgba(0, 0, 0, .11);
 }
 .category-illustration {
   height: 88px;
   margin-bottom: 16px;
   border-radius: 8px;
   background: #f2f3f8;
   color: #1769aa;
 }
 .category-illustration > .material-symbols-outlined {
   font-size: 42px;
   font-variation-settings: 'FILL' 0;
 }
