 .category-description {
   min-height: 60px;
   margin-top: 6px;
   color: #666563;
   font-size: .86rem;
   line-height: 1.45;
 }
 .category-action {
   padding-top: 12px;
   color: #1769aa;
   font-size: .84rem;
   font-weight: 600;
 }
 .page-heading .brand-eyebrow { color: #1769aa; }

