   .sidebar-brand { min-height: 44px; margin: 0 4px 13px; }
   .sidebar-brand img { width: 80px; }
   .workspace { min-height: calc(100vh - 56px); padding: 0 18px 32px; }
   .dashboard-view { min-height: calc(100vh - 56px); }
   .dashboard-hero { min-height: 160px; padding-top: 28px; }
   .category-card { width: min(100%, 330px); }
 }

